[package]
name = "spectraplex-api"
version = "0.1.0"
edition = "2021"

[dependencies]
spectraplex-core = { path = "../core" }
spectraplex-adapters = { path = "../adapters" }
axum = "0.8"
tokio = { version = "1", features = ["full"] }
serde = { version = "1.0", features = ["derive"] }
