            get(get_single_transaction),
        )
        .route("/v1/stats/{wallet}", get(get_wallet_stats))
        .route("/v1/stream/start", post(start_stream))
        .route("/v1/stream/{stream_id}/stop", post(stop_stream))
        .route("/v1/streams", get(list_streams))

