                .query_hl_fill_records(
                    params.target_id,
                    net,
                    params.time_start,
                    params.time_end,
                    limit,
                    offset,
                )
                .await
                .map_err(AppError::internal)?;
            serde_json::to_value(&records).map_err(AppError::internal)?
        }
        "hl_funding" => {
            let records = state
                .repo
                .query_hl_funding_payments(
                    params.target_id,
                    net,
                    params.time_start,
                    params.time_end,
                    limit,
                    offset,
                )
                .await
                .map_err(AppError::internal)?;
            serde_json::to_value(&records).map_err(AppError::internal)?
        }
        "positions" => {
            let records = state
                .repo
                .query_hl_position_changes(
                    params.target_id,
                    net,
                    params.time_start,
                    params.time_end,
                    limit,
                    offset,
                )
                .await
                .map_err(AppError::internal)?;
            serde_json::to_value(&records).map_err(AppError::internal)?
        }
        _ => unreachable!("dataset name validated above"),
    };

    Ok(Json(result))
}

async fn get_dataset_completeness_handler(
    State(state): State<Arc<AppState>>,
    Path(name): Path<String>,
) -> Result<Json<Vec<DatasetCompleteness>>, AppError> {
    validate_dataset_name(&name)?;
    let records = state
        .repo
        .list_completeness_by_dataset(&name)
        .await
        .map_err(AppError::internal)?;
    Ok(Json(records))
}

