#[test]
fn test_wallet_stats_serialization() {
    let stats = WalletStats {
        total_transactions: 42,
        earliest_timestamp: Some(1700000000),
        latest_timestamp: Some(1700100000),
        total_chains: 2,
        unique_assets: 5,
