 970→// ---------------------------------------------------------------------------
 971→// Dataset filter query builder (P4-W1)
 972→// ---------------------------------------------------------------------------
 973→
 974→/// Build a filtered SELECT query for a Silver dataset table.
 975→///
 976→/// Dynamically adds JOIN and WHERE clauses based on which filters are
 977→/// provided, avoiding unnecessary JOINs when filters are unused.
 978→/// Uses `raw_transactions.timestamp` for time-window filtering so that
 979→/// time_start/time_end are always in the same units (seconds since epoch).
 980→#[allow(clippy::too_many_arguments)]
 981→pub fn build_dataset_filter_query(
 982→    select_cols: &str,
 983→    table_name: &str,
 984→    order_col: &str,
 985→    target_id: Option<Uuid>,
 986→    network: Option<&str>,
 987→    time_start: Option<i64>,
 988→    time_end: Option<i64>,
 989→    limit: i64,
 990→    offset: i64,
 991→) -> anyhow::Result<(String, sqlx::postgres::PgArguments)> {
 992→    let mut sql = format!("SELECT {select_cols} FROM {table_name} dt");
 993→    let mut args = sqlx::postgres::PgArguments::default();
 994→    let mut n: usize = 0;
 995→    let mut wheres: Vec<String> = Vec::new();
 996→
 997→    if target_id.is_some() {
 998→        sql.push_str(" JOIN target_matches tm ON tm.raw_transaction_id = dt.raw_transaction_id");
 999→    }
1000→    if time_start.is_some() || time_end.is_some() {
1001→        sql.push_str(" JOIN raw_transactions rt ON rt.id = dt.raw_transaction_id");
1002→    }
1003→
1004→    if let Some(tid) = target_id {
1005→        n += 1;
1006→        wheres.push(format!("tm.target_id = ${n}"));
1007→        use sqlx::Arguments;
1008→        args.add(tid).map_err(|e| anyhow::anyhow!("{e}"))?;
1009→    }
1010→    if let Some(net) = network {
1011→        n += 1;
1012→        wheres.push(format!("dt.network = ${n}"));
1013→        use sqlx::Arguments;
1014→        args.add(net.to_string())
1015→            .map_err(|e| anyhow::anyhow!("{e}"))?;
1016→    }
1017→    if let Some(start) = time_start {
1018→        n += 1;
1019→        wheres.push(format!("rt.timestamp >= ${n}"));
1020→        use sqlx::Arguments;
1021→        args.add(start).map_err(|e| anyhow::anyhow!("{e}"))?;
1022→    }
1023→    if let Some(end) = time_end {
1024→        n += 1;
1025→        wheres.push(format!("rt.timestamp <= ${n}"));
1026→        use sqlx::Arguments;
1027→        args.add(end).map_err(|e| anyhow::anyhow!("{e}"))?;
1028→    }
1029→
1030→    if !wheres.is_empty() {
1031→        sql.push_str(" WHERE ");
1032→        sql.push_str(&wheres.join(" AND "));
1033→    }
1034→
1035→    n += 1;
1036→    let lim_n = n;
1037→    n += 1;
1038→    let off_n = n;
1039→    sql.push_str(&format!(
1040→        " ORDER BY {order_col} DESC LIMIT ${lim_n} OFFSET ${off_n}"
1041→    ));
1042→    use sqlx::Arguments;
1043→    args.add(limit).map_err(|e| anyhow::anyhow!("{e}"))?;
1044→    args.add(offset).map_err(|e| anyhow::anyhow!("{e}"))?;
1045→
1046→    Ok((sql, args))
1047→}
