//! V2 repository methods for canonical bronze data and control-plane tables.
//!
//! All methods are added as `impl Repository` so callers use the same
//! `Repository` value they already hold for V1 wallet-scoped queries.

use chrono::{DateTime, Utc};
use spectraplex_core::materializer::{
    DecodedEvent, HlFillRecord, HlFundingPayment, HlPositionChange, NativeBalanceDelta,
    TokenTransfer,
};
use spectraplex_core::v2::{
    ChainFamily, Checkpoint, CompletenessStatus, DatasetCompleteness, DatasetVersion,
    DatasetVersionStatus, IndexTarget, IngestionRun, Network, RawTransaction, TargetKind,
    TargetMatch, TargetMode,
};
use sqlx::Row;
