fn token_transfers_to_csv(
    records: &[spectraplex_core::materializer::TokenTransfer],
) -> Vec<u8> {
    let mut buf = String::from(
        "id,raw_transaction_id,network,token_address,token_symbol,from_address,to_address,amount,decimals,dataset_version_id,created_at\n",
    );
    for r in records {
        buf.push_str(&format!(
            "{},{},{},{},{},{},{},{},{},{},{}\n",
            r.id,
            r.raw_transaction_id.map(|u| u.to_string()).unwrap_or_default(),
            csv_escape(&r.network),
            csv_escape(&r.token_address),
            r.token_symbol.as_deref().unwrap_or(""),
            csv_escape(&r.from_address),
            csv_escape(&r.to_address),
            r.amount,
            r.decimals,
            r.dataset_version_id.map(|u| u.to_string()).unwrap_or_default(),
            r.created_at.to_rfc3339(),
        ));
    }
    buf.into_bytes()
}

