        let txs = vec![
            make_tx(
                Chain::Solana,
                "sig1",
                100,
                serde_json::json!({"slot": 5000}),
            ),
            make_tx(
                Chain::Solana,
                "sig2",
                200,
                serde_json::json!({"slot": 6000}),
            ),
        ];
