    #[test]
    fn test_job_state_variants_serialize() {
        for (variant, expected) in [
            (JobState::Pending, "pending"),
            (JobState::Running, "running"),
            (JobState::Completed, "completed"),
            (JobState::Failed, "failed"),
        ] {
            let status = JobStatus {
                id: Uuid::nil(),
                state: variant,
                message: None,
