    for r in records {
        buf.push_str(&format!(
            "{},{},{},{},{},{},{},{},{},{},{}\n",
            r.id,
            r.raw_transaction_id
                .map(|u| u.to_string())
                .unwrap_or_default(),
            csv_escape(&r.network),
            csv_escape(&r.token_address),
            r.token_symbol.as_deref().unwrap_or(""),
            csv_escape(&r.from_address),
            csv_escape(&r.to_address),
